import{_ as n,o as r,c as t,a2 as s}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Premier lancement","description":"","frontmatter":{},"headers":[],"relativePath":"guide/premier-lancement.md","filePath":"guide/premier-lancement.md"}'),o={name:"guide/premier-lancement.md"};function a(i,e,l,u,c,d){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="premier-lancement" tabindex="-1">Premier lancement <a class="header-anchor" href="#premier-lancement" aria-label="Permalink to &quot;Premier lancement&quot;">​</a></h1><p>Au premier lancement, Kodus te demande ton pseudo, puis te fait créer ta première instance (ta « partie » de Minecraft, voir <a href="./lexique">les mots à connaître</a>).</p><ol><li><strong>Choisis ton pseudo</strong> : 3 à 16 caractères, lettres, chiffres ou <code>_</code>. C&#39;est le nom que les autres verront en jeu. Tu pourras le changer dans les <strong>Paramètres</strong> (l&#39;engrenage en haut à droite de l&#39;accueil).</li><li><strong>Crée une instance</strong> dans la fenêtre « Nouvelle instance » : <ul><li><strong>Nom</strong> : ce que tu veux, par exemple « Survie entre potes ».</li><li><strong>Version</strong> : la version de Minecraft. Si tu rejoins un serveur, prends la même que lui. Sinon, la plus récente proposée est un bon choix.</li><li><strong>Loader</strong> : laisse <strong>Fabric</strong> (coché par défaut) si tu veux des mods, ou <strong>Vanilla</strong> pour le jeu de base. Les loaders grisés n&#39;existent pas pour cette version.</li><li><strong>RAM allouée</strong> : n&#39;y touche pas.</li></ul></li><li>Clique <strong>Créer</strong>, puis sur le gros bouton <strong>Jouer</strong> de l&#39;accueil.</li></ol><div class="info custom-block"><p class="custom-block-title">Le premier lancement est long, c&#39;est normal</p><p>Kodus télécharge Java et le jeu (plusieurs centaines de Mo). La barre de progression sous le bouton te montre où il en est. Les fois suivantes, c&#39;est quasi instantané.</p></div><h2 id="l-accueil-en-bref" tabindex="-1">L&#39;accueil en bref <a class="header-anchor" href="#l-accueil-en-bref" aria-label="Permalink to &quot;L&#39;accueil en bref&quot;">​</a></h2><ul><li><strong>Jouer</strong> et le menu en dessous : lance l&#39;instance choisie.</li><li><strong>Temps de jeu</strong> et <strong>Monde le plus joué</strong> : tes stats pour cette instance.</li><li><strong>L&#39;icône image</strong> en haut à droite : toutes tes captures d&#39;écran (touche F2 en jeu), filtrables par instance.</li><li><strong>L&#39;engrenage</strong> : les Paramètres (pseudo, skin, animation de fond, mises à jour).</li><li><strong>La colonne de gauche</strong> : tes instances. Un clic ouvre la page de l&#39;instance (mods, logs, réglages). Le logo Kodus en haut ramène à l&#39;accueil.</li></ul>',6)])])}const p=n(o,[["render",a]]);export{m as __pageData,p as default};
